import test from 'node:test';import assert from 'node:assert/strict';import {validatePrototypeMutation} from './prototype-policy.js';
const base=()=>({school:{name:'IAE'},settings:{},routes:[],levels:[],staff:[],permissions:{},students:[{id:'e1',titulares:['p1','p2']},{id:'e2',titulares:['p3']}],persons:[{id:'p1'},{id:'p2'},{id:'p3'}],authorizations:[],requests:[],notifications:[],chats:{},chatState:{},log:[],busTrips:{today_r1_vuelta:{status:'en_ruta',boarded:{e1:{status:'abordo'},e2:{status:'abordo'}},noBus:[]}}});const parent={id:'parent-carlos',role:'parent',prototypeIdentity:{personId:'p1'}};
test('parent cannot overwrite school or staff state',()=>{const a=base(),b=structuredClone(a);b.school.name='attacker';assert.throws(()=>validatePrototypeMutation(a,b,parent),/forbidden_prototype_field:school/)});
test('parent can add own linked-child request but not another family request',()=>{const a=base(),b=structuredClone(a);b.requests.push({id:'r1',studentId:'e1',requestedBy:'p1',status:'pendiente'});assert.equal(validatePrototypeMutation(a,b,parent),true);const c=structuredClone(a);c.requests.push({id:'r2',studentId:'e2',requestedBy:'p1',status:'pendiente'});assert.throws(()=>validatePrototypeMutation(a,c,parent),/forbidden_parent_request_owner/)});
test('co-guardian may confirm or cancel a linked-student request',()=>{const a=base();a.requests=[{id:'r1',kind:'salida',studentId:'e1',requestedBy:'p2',status:'aprobada',code:'1234'}];const confirmed=structuredClone(a);confirmed.requests[0].confirmation={status:'confirmada',byPerson:'p1'};assert.equal(validatePrototypeMutation(a,confirmed,parent),true);const cancelled=structuredClone(a);cancelled.requests[0].status='cancelada';assert.equal(validatePrototypeMutation(a,cancelled,parent),true)});
test('parent cannot confirm or cancel a request from another family',()=>{const a=base();a.requests=[{id:'r2',kind:'salida',studentId:'e2',requestedBy:'p3',status:'aprobada'}];const b=structuredClone(a);b.requests[0].confirmation={status:'confirmada',byPerson:'p1'};assert.throws(()=>validatePrototypeMutation(a,b,parent),/forbidden_parent_request_family/)});
test('parent may set bus opt-out for own child only',()=>{const a=base(),b=structuredClone(a);b.busTrips.today_r1_vuelta.noBus.push('e1');assert.equal(validatePrototypeMutation(a,b,parent),true);const c=structuredClone(a);c.busTrips.today_r1_vuelta.noBus.push('e2');assert.throws(()=>validatePrototypeMutation(a,c,parent),/forbidden_parent_bus_family/)});
test('parent cannot change trip status or another childs boarding',()=>{const a=base(),b=structuredClone(a);b.busTrips.today_r1_vuelta.status='finalizado';assert.throws(()=>validatePrototypeMutation(a,b,parent),/forbidden_parent_bus_family/);const c=structuredClone(a);c.busTrips.today_r1_vuelta.boarded.e2.status='bajo';assert.throws(()=>validatePrototypeMutation(a,c,parent),/forbidden_parent_bus_family/)});
test('reception can approve but gate can only mark an approved request retired',()=>{const a=base();a.requests=[{id:'r1',studentId:'e1',requestedBy:'p1',status:'pendiente'}];const approved=structuredClone(a);approved.requests[0].status='aprobada';assert.equal(validatePrototypeMutation(a,approved,{role:'reception'}),true);assert.throws(()=>validatePrototypeMutation(a,approved,{role:'gate'}),/forbidden_gate_request_change/);const retired=structuredClone(approved);retired.requests[0].status='retirado';assert.equal(validatePrototypeMutation(approved,retired,{role:'gate'}),true)});
test('server identity bindings distinguish the two guardians',async()=>{const {connectedSeed}=await import('./seed.js');const s=connectedSeed();assert.deepEqual(s.users.find(x=>x.id==='parent-carlos').prototypeIdentity,{personId:'p1',phoneId:'p1'});assert.deepEqual(s.users.find(x=>x.id==='parent-ana').prototypeIdentity,{personId:'p2',phoneId:'p2'})});
